const express = require('express');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// ADMIN CONFIGURATION: generated by the offline admin page.
// These values are deliberately kept on the server and are not sent to browsers.
const financeConfig = Object.freeze({
  minimumLoan: 20000,
  maximumLoan: 250000,
  documentFee: 495,
  tiers: [
    { upTo: 50000, rate: 0.0995, brokerMultiplier: 1.05, dofBase: 0 },
    { upTo: 100000, rate: 0.0945, brokerMultiplier: 1.04, dofBase: 0 },
    { upTo: 200000, rate: 0.0945, brokerMultiplier: 1.035, dofBase: 0 },
    { upTo: 300000, rate: 0.0945, brokerMultiplier: 1.0325, dofBase: 0 }
  ]
});

app.disable('x-powered-by');
app.use(express.json({ limit: '20kb' }));
app.use(express.static(path.join(__dirname, 'public')));

function finiteNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function selectTier(amount) {
  return financeConfig.tiers.find(tier => amount < tier.upTo) || financeConfig.tiers[financeConfig.tiers.length - 1];
}

function payment(ratePerPeriod, numberOfPeriods, presentValue, futureValue = 0, paymentTiming = 1) {
  if (ratePerPeriod === 0) return -(presentValue + futureValue) / numberOfPeriods;
  const factor = Math.pow(1 + ratePerPeriod, numberOfPeriods);
  return -(ratePerPeriod * (futureValue + factor * presentValue)) / ((1 + ratePerPeriod * paymentTiming) * (factor - 1));
}

app.post('/api/calculate', (req, res) => {
  const equipmentPrice = finiteNumber(req.body.equipmentPrice);
  const deposit = finiteNumber(req.body.deposit);
  const energySavings = finiteNumber(req.body.energySavings);

  if ([equipmentPrice, deposit, energySavings].includes(null)) {
    return res.status(400).json({ error: 'Enter valid numeric values in all three fields.' });
  }
  if (equipmentPrice < 0 || deposit < 0 || energySavings < 0) {
    return res.status(400).json({ error: 'Values cannot be negative.' });
  }
  if (deposit > equipmentPrice) {
    return res.status(400).json({ error: 'The deposit cannot exceed the equipment price.' });
  }

  const requestedLoan = equipmentPrice - deposit;
  if (requestedLoan < financeConfig.minimumLoan || requestedLoan > financeConfig.maximumLoan) {
    return res.json({
      valid: false,
      loanAmount: requestedLoan,
      message: `The finance amount must be between $${financeConfig.minimumLoan.toLocaleString('en-AU')} and $${financeConfig.maximumLoan.toLocaleString('en-AU')}. Larger amounts are quoted individually.`
    });
  }

  const tier = selectTier(requestedLoan);
  const financedAmount = requestedLoan * tier.brokerMultiplier + financeConfig.documentFee + tier.dofBase;
  const terms = [36, 48, 60];
  const results = terms.map(term => {
    const financePayment = Math.ceil(payment(tier.rate / 12, term, -financedAmount, 0, 1));
    return { term, financePayment, energySavings: -energySavings, netCost: financePayment - energySavings };
  });

  res.json({ valid: true, loanAmount: requestedLoan, results });
});

app.get('*', (_req, res) => res.sendFile(path.join(__dirname, 'public', 'index.html')));
app.listen(PORT, () => console.log(`Solar Finance calculator running on port ${PORT}`));
